import { useState, useRef, useEffect, Fragment } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import {
  User,
  LogOut,
  Loader2,
  Users,
  CheckCircle2,
  Cloud,
  CloudOff,
  ChevronDown,
  Download,
  Upload,
  Database,
  AlertTriangle,
} from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { toast } from 'sonner';
import { downloadBackup, importBackup } from '@/lib/dataBackup';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import type { ThemeConfig } from '@/lib/theme';
import type { SyncStatus } from '@/hooks/useDataSync';
import { Switch } from '@/components/ui/switch';
import { Sparkles, Cpu } from 'lucide-react';
import { getTokenUsage, getAISettings, setAISettings, formatTokenCount } from '@/lib/ai-client';
import api from '@/lib/api';
import { logger } from '@lark-apaas/client-toolkit-lite';

interface AuthDialogProps {
  theme: ThemeConfig;
  syncStatus?: SyncStatus;
  onOpenTeamPanel?: () => void;
  trigger?: React.ReactNode;
}

export default function AuthDialog({ theme, syncStatus = 'idle', onOpenTeamPanel, trigger }: AuthDialogProps) {
  const { user, isLoggedIn, login, register, logout } = useAuth();
  const [open, setOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [backupOpen, setBackupOpen] = useState(false);
  const [confirmImportOpen, setConfirmImportOpen] = useState(false);
  const [pendingFile, setPendingFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // AI 设置
  const [aiSettings, setAiSettingsState] = useState(() => getAISettings());
  const [tokenUsage, setTokenUsage] = useState(() => getTokenUsage());

  // 待审批数量：登录后每 30 秒轮询一次，有新申请时头像显示红点
  const [pendingCount, setPendingCount] = useState(0);
  useEffect(() => {
    if (!isLoggedIn) {
      setPendingCount(0);
      return;
    }
    // 只有管理员/主账号角色才需要查 pending
    const role = user?.role || '';
    if (!role || role === 'sub_account') return;

    let cancelled = false;
    async function fetchPending() {
      try {
        const res = await api.get('/auth/pending-count');
        if (!cancelled) {
          setPendingCount(Number((res.data as any)?.count || 0));
        }
      } catch (e) {
        // 静默失败，不影响主流程
        logger.warn('[auth] pending-count 拉取失败', String(e));
      }
    }
    fetchPending();
    const timer = setInterval(fetchPending, 30000);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [isLoggedIn, user?.role]);

  // 打开备份弹窗时刷新用量显示
  useEffect(() => {
    if (backupOpen) {
      setTokenUsage(getTokenUsage());
      setAiSettingsState(getAISettings());
    }
  }, [backupOpen]);

  function toggleAIAutoGenerate(checked: boolean) {
    const next = setAISettings({ autoGenerate: checked });
    setAiSettingsState(next);
    toast.success(checked ? '已开启 AI 自动调用' : '已关闭 AI 自动调用，需手动点击生成');
  }

  // 登录表单
  const [loginUsername, setLoginUsername] = useState('');
  const [loginPassword, setLoginPassword] = useState('');

  // 注册表单
  const [regUsername, setRegUsername] = useState('');
  const [regPassword, setRegPassword] = useState('');
  const [regNickname, setRegNickname] = useState('');
  const [regParent, setRegParent] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginUsername || !loginPassword) {
      toast.error('请输入用户名和密码');
      return;
    }
    setIsSubmitting(true);
    try {
      await login(loginUsername, loginPassword);
      toast.success('登录成功');
      setOpen(false);
      setLoginUsername('');
      setLoginPassword('');
    } catch (err: any) {
      toast.error(err.message || '登录失败');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!regUsername || !regPassword) {
      toast.error('请输入用户名和密码');
      return;
    }
    setIsSubmitting(true);
    try {
      const result = await register(regUsername, regPassword, regNickname || undefined, regParent || undefined);
      if (result.autoLoggedIn) {
        toast.success('注册成功，已自动登录');
      } else {
        toast.success('注册申请已提交，请等待主账号审批通过后登录');
      }
      setOpen(false);
      setRegUsername('');
      setRegPassword('');
      setRegNickname('');
      setRegParent('');
    } catch (err: any) {
      toast.error(err.message || '注册失败');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleLogout = async () => {
    await logout();
    toast.success('已退出登录');
  };

  const syncLabel = {
    idle: '已同步',
    syncing: '同步中',
    synced: '已同步',
    error: '同步失败',
  }[syncStatus];

  const syncColor = {
    idle: theme.primary,
    syncing: theme.primaryLight,
    synced: theme.primary,
    error: theme.priority.p0,
  }[syncStatus];

  // 已登录：头像下拉菜单
  if (isLoggedIn && user) {
    const isSuperAdmin = user.role === 'super_admin' || user.role === 'admin';
    // 能看到团队管理入口的：super_admin / admin / 普通 user（主账号可以管理自己的子账号）
    const canManageTeam = isLoggedIn && user?.role !== 'sub_account';
    const initial = (user.nickname || user.username).charAt(0).toUpperCase();

    return (
      <Fragment>
        <div className="flex items-center gap-2">
        {/* 同步状态指示 */}
        {isLoggedIn && (
          <div className="hidden lg:flex items-center gap-1 text-xs" style={{ color: syncColor }}>
            {syncStatus === 'syncing' ? (
              <Loader2 className="size-3 animate-spin" />
            ) : syncStatus === 'error' ? (
              <CloudOff className="size-3" />
            ) : (
              <Cloud className="size-3" />
            )}
            <span>{syncLabel}</span>
          </div>
        )}

        <DropdownMenu>
           <DropdownMenuTrigger asChild>
             <Button
               variant="ghost"
               size="sm"
               className="h-8 px-1.5 gap-2 pl-1.5 relative"
             >
               <div className="relative">
                 <div
                   className="size-6 rounded-full flex items-center justify-center text-xs font-bold text-white shrink-0"
                   style={{ backgroundColor: theme.primary }}
                 >
                   {initial}
                 </div>
                 {pendingCount > 0 && (
                   <span
                     className="absolute -top-0.5 -right-0.5 size-3.5 rounded-full text-white text-[9px] font-bold flex items-center justify-center leading-none"
                     style={{ backgroundColor: '#ef4444' }}
                   >
                     {pendingCount > 9 ? '9+' : pendingCount}
                   </span>
                 )}
               </div>
               <span className="text-xs font-medium hidden sm:inline max-w-[80px] truncate">
                 {user.nickname || user.username}
               </span>
               <ChevronDown className="size-3 text-muted-foreground hidden sm:inline" />
             </Button>
           </DropdownMenuTrigger>
          <DropdownMenuContent
            align="end"
            className="w-52"
            style={{
              backgroundColor: theme.ui.glassBg,
              backdropFilter: 'blur(16px) saturate(180%)',
              WebkitBackdropFilter: 'blur(16px) saturate(180%)',
              borderColor: theme.ui.cardBorder,
            }}
          >
            <DropdownMenuLabel>
              <div className="flex items-center gap-2">
                <div
                  className="size-8 rounded-full flex items-center justify-center text-xs font-bold text-white"
                  style={{ backgroundColor: theme.primary }}
                >
                  {initial}
                </div>
                <div className="min-w-0">
                  <div className="text-sm font-semibold truncate">{user.nickname || user.username}</div>
                  <div className="text-[10px] text-muted-foreground truncate">@{user.username}</div>
                </div>
              </div>
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-xs flex items-center gap-2 cursor-default"
              style={{ color: syncColor }}
            >
              {syncStatus === 'syncing' ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : syncStatus === 'error' ? (
                <CloudOff className="size-3.5" />
              ) : (
                <CheckCircle2 className="size-3.5" />
              )}
              个人数据：{syncLabel}
            </DropdownMenuItem>
             {canManageTeam && (
               <>
                 <DropdownMenuSeparator />
                 <DropdownMenuItem
                   className="text-xs gap-2 cursor-pointer"
                   onClick={() => {
                     onOpenTeamPanel?.();
                   }}
                 >
                   <div className="flex-1 flex items-center gap-2">
                     <Users className="size-3.5" style={{ color: theme.primary }} />
                     <span>团队管理</span>
                   </div>
                   {pendingCount > 0 && (
                     <span
                       className="text-[10px] px-1.5 py-0.5 rounded-full text-white font-medium"
                       style={{ backgroundColor: '#ef4444' }}
                     >
                       {pendingCount}待审
                     </span>
                   )}
                 </DropdownMenuItem>
               </>
             )}
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-xs gap-2 cursor-pointer flex justify-between items-center"
              onClick={(e) => e.preventDefault()}
            >
              <div className="flex items-center gap-2">
                <Cpu className="size-3.5" style={{ color: theme.primary }} />
                <span>本月已用 Token</span>
              </div>
              <span className="font-medium tabular-nums" style={{ color: theme.primary }}>
                {formatTokenCount(tokenUsage.totalTokens)}
              </span>
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-xs gap-2 cursor-pointer"
              onClick={() => setBackupOpen(true)}
            >
              <Database className="size-3.5" style={{ color: theme.primary }} />
              <span>数据备份与恢复</span>
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="text-xs gap-2 cursor-pointer text-destructive"
              onClick={handleLogout}
            >
              <LogOut className="size-3.5" />
              退出登录
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
        </div>

        {/* 数据备份弹窗 */}
      <Dialog open={backupOpen} onOpenChange={setBackupOpen}>
        <DialogContent
          className="sm:max-w-md"
          style={{
            backgroundColor: theme.ui.glassBg,
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            borderColor: theme.ui.cardBorder,
          }}
        >
          <DialogHeader>
            <DialogTitle style={{ color: theme.primaryDark }}>
              数据备份与恢复
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <p className="text-xs text-muted-foreground">
              把本地所有数据导出为 JSON 文件，可随时导入恢复。云端已同步的数据不受影响。
            </p>
            <div className="grid grid-cols-2 gap-3">
              <Button
                variant="outline"
                onClick={downloadBackup}
                className="flex-col h-auto py-4 gap-2"
              >
                <Download className="size-5" />
                <span className="text-xs font-medium">导出备份</span>
              </Button>
              <Button
                variant="outline"
                onClick={() => fileInputRef.current?.click()}
                className="flex-col h-auto py-4 gap-2"
              >
                <Upload className="size-5" />
                <span className="text-xs font-medium">导入恢复</span>
              </Button>
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept=".json,application/json"
              className="hidden"
              onChange={async (e) => {
                const file = e.target.files?.[0];
                if (!file) return;
                setPendingFile(file);
                setConfirmImportOpen(true);
                e.target.value = '';
              }}
            />
            <p className="text-[10px] text-muted-foreground">
              支持模块：采购订单、时效记录、物流配置、每日待办、笔记/灵感、AI技巧本、主题偏好、账号信息等
            </p>

            {/* AI 用量与设置 */}
            <div className="border-t border-border/40 pt-4 space-y-3">
              <div className="flex items-center gap-2">
                <Sparkles className="size-4" style={{ color: theme.primary }} />
                <span className="text-sm font-medium" style={{ color: theme.primaryDark }}>
                  AI 服务设置
                </span>
              </div>

              <div className="grid grid-cols-2 gap-3 text-xs">
                <div className="bg-muted/50 rounded-lg p-3">
                  <div className="text-muted-foreground mb-1">本月使用</div>
                  <div className="text-lg font-bold tabular-nums" style={{ color: theme.primary }}>
                    {formatTokenCount(tokenUsage.totalTokens)}
                  </div>
                  <div className="text-[10px] text-muted-foreground">Token 总量</div>
                </div>
                <div className="bg-muted/50 rounded-lg p-3">
                  <div className="text-muted-foreground mb-1">输入 / 输出</div>
                  <div className="text-sm font-semibold tabular-nums text-foreground">
                    {formatTokenCount(tokenUsage.inputTokens)} / {formatTokenCount(tokenUsage.outputTokens)}
                  </div>
                  <div className="text-[10px] text-muted-foreground">仅本地统计</div>
                </div>
              </div>

              <div className="flex items-center justify-between py-2">
                <div className="space-y-0.5">
                  <div className="text-sm font-medium text-foreground">自动调用 AI</div>
                  <div className="text-[10px] text-muted-foreground">
                    关闭后需手动点击「AI 生成」按钮才会调用，节省用量
                  </div>
                </div>
                <Switch
                  checked={aiSettings.autoGenerate}
                  onCheckedChange={toggleAIAutoGenerate}
                />
              </div>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* 导入确认 */}
      <AlertDialog open={confirmImportOpen} onOpenChange={setConfirmImportOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertTriangle className="size-5 text-amber-500" />
              确认导入备份？
            </AlertDialogTitle>
            <AlertDialogDescription>
              导入将覆盖当前本地数据，此操作不可撤销。建议先导出当前数据作为备份。
              {pendingFile && (
                <div className="mt-2 text-xs text-muted-foreground">
                  文件名：{pendingFile.name}（{(pendingFile.size / 1024).toFixed(1)} KB）
                </div>
              )}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setPendingFile(null)}>取消</AlertDialogCancel>
            <AlertDialogAction
              className="bg-primary text-primary-foreground"
              onClick={async () => {
                if (!pendingFile) return;
                try {
                  const result = await importBackup(pendingFile);
                  if (result.success) {
                    toast.success(`已恢复 ${result.imported.length} 个模块，页面将刷新`);
                    setTimeout(() => window.location.reload(), 1200);
                  } else {
                    toast.error('导入失败');
                  }
                } catch (e) {
                  toast.error('导入出错');
                } finally {
                  setPendingFile(null);
                  setConfirmImportOpen(false);
                  setBackupOpen(false);
                }
              }}
            >
              确认导入
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      </Fragment>
    );
  }

  // 未登录：登录按钮 + 弹窗
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {trigger || (
          <Button
            variant="ghost"
            size="sm"
            className="h-7 px-2 text-xs gap-1"
          >
            <User className="size-3.5" />
            登录
          </Button>
        )}
      </DialogTrigger>
      <DialogContent
        className="sm:max-w-md"
        style={{
          backgroundColor: theme.ui.glassBg,
          backdropFilter: 'blur(20px) saturate(180%)',
          WebkitBackdropFilter: 'blur(20px) saturate(180%)',
          borderColor: theme.ui.cardBorder,
        }}
      >
        <DialogHeader>
          <DialogTitle style={{ color: theme.primaryDark }}>
            鑫之海运营手册账号
          </DialogTitle>
        </DialogHeader>

        <Tabs defaultValue="login" className="w-full">
          <TabsList className="w-full mb-4">
            <TabsTrigger value="login" className="flex-1">登录</TabsTrigger>
            <TabsTrigger value="register" className="flex-1">注册</TabsTrigger>
          </TabsList>

          <TabsContent value="login">
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="space-y-2">
                <Label>用户名</Label>
                <Input
                  value={loginUsername}
                  onChange={(e) => setLoginUsername(e.target.value)}
                  placeholder="请输入用户名"
                  autoComplete="username"
                />
              </div>
              <div className="space-y-2">
                <Label>密码</Label>
                <Input
                  type="password"
                  value={loginPassword}
                  onChange={(e) => setLoginPassword(e.target.value)}
                  placeholder="请输入密码"
                  autoComplete="current-password"
                />
              </div>
              <Button
                type="submit"
                className="w-full"
                disabled={isSubmitting}
                style={{ backgroundColor: theme.primary }}
              >
                {isSubmitting && <Loader2 className="size-4 mr-2 animate-spin" />}
                登录
              </Button>
              <p className="text-xs text-center text-muted-foreground">
                未注册账号将自动以游客模式使用，数据存储在本地
              </p>
            </form>
          </TabsContent>

          <TabsContent value="register">
            <form onSubmit={handleRegister} className="space-y-4">
              <div className="space-y-2">
                <Label>用户名</Label>
                <Input
                  value={regUsername}
                  onChange={(e) => setRegUsername(e.target.value)}
                  placeholder="请设置用户名"
                  autoComplete="username"
                />
              </div>
              <div className="space-y-2">
                <Label>昵称（可选）</Label>
                <Input
                  value={regNickname}
                  onChange={(e) => setRegNickname(e.target.value)}
                  placeholder="显示名称"
                />
              </div>
              <div className="space-y-2">
                <Label>密码</Label>
                <Input
                  type="password"
                  value={regPassword}
                  onChange={(e) => setRegPassword(e.target.value)}
                  placeholder="至少6位"
                  autoComplete="new-password"
                />
              </div>
              <div className="space-y-2">
                <Label>邀请主账号（可选）</Label>
                <Input
                  value={regParent}
                  onChange={(e) => setRegParent(e.target.value)}
                  placeholder="填写主账号用户名，审批后加入其团队"
                  autoComplete="off"
                />
                <p className="text-[11px] text-muted-foreground">
                  不填则由超级管理员审批
                </p>
              </div>
              <Button
                type="submit"
                className="w-full"
                disabled={isSubmitting}
                style={{ backgroundColor: theme.primary }}
              >
                {isSubmitting && <Loader2 className="size-4 mr-2 animate-spin" />}
                注册并登录
              </Button>
            </form>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}
