import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';
import { SHARED_KEYS } from '@/hooks/useSharedData';

// 数据备份格式版本
export const BACKUP_VERSION = 1;

export interface BackupData {
  version: number;
  exportedAt: string;
  app: string;
  modules: Record<string, unknown>;
}

/**
 * 收集所有本地存储数据，生成备份 JSON
 * 只收集已知 key，避免把无关数据也导出去
 */
const BACKUP_KEYS: { key: string; isJson: boolean; label: string }[] = [
  // 采购模块
  { key: SHARED_KEYS.purchaseOrders, isJson: true, label: '采购订单' },
  { key: SHARED_KEYS.leadTimeRecords, isJson: true, label: '时效记录' },
  { key: SHARED_KEYS.logisticsConfig, isJson: true, label: '物流配置' },
  { key: SHARED_KEYS.commonShops, isJson: true, label: '常用店铺' },
  { key: 'kuaidi100_api_key_v1', isJson: false, label: '快递100密钥' },
  // 笔记/灵感
  { key: SHARED_KEYS.inspirationNotes, isJson: true, label: '灵感笔记' },
  { key: SHARED_KEYS.aiTips, isJson: true, label: 'AI技巧本' },
  { key: SHARED_KEYS.operationNotes, isJson: true, label: '运营笔记' },
  { key: SHARED_KEYS.viralShortsImages, isJson: true, label: '爆款二创' },
  // 工作台
  { key: 'daily-checkins', isJson: true, label: '打卡记录' },
  // 待办（所有日期前缀） — 特别处理
  { key: '__TODO_SCAN__', isJson: true, label: '每日待办' },
  // 主题偏好
  { key: 'seasonal-theme-override', isJson: false, label: '主题偏好' },
  // 团队/账号
  { key: 'auth_accounts', isJson: true, label: '账号信息' },
  { key: 'auth_token', isJson: false, label: '登录令牌' },
  { key: 'auth_user', isJson: true, label: '用户信息' },
  // 读报已读标记等
  { key: 'read_news_ids', isJson: true, label: '已读新闻' },
];

const TODOS_PREFIX = 'todo-items:';

function scanTodoKeys(): string[] {
  try {
    const keys: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.includes(TODOS_PREFIX)) {
        // 提取干净的 key（去掉 app 前缀）
        const cleanKey = k.includes(':') && k.indexOf(TODOS_PREFIX) > 0
          ? k.slice(k.indexOf(TODOS_PREFIX))
          : k;
        keys.push(cleanKey);
      }
    }
    return keys;
  } catch {
    return [];
  }
}

export function exportAllData(): BackupData {
  const modules: Record<string, unknown> = {};
  const meta: Record<string, string> = {};

  for (const entry of BACKUP_KEYS) {
    try {
      if (entry.key === '__TODO_SCAN__') {
        const todoKeys = scanTodoKeys();
        const todos: Record<string, unknown> = {};
        for (const tk of todoKeys) {
          const raw = scopedStorage.getItem(tk);
          if (raw) {
            try {
              todos[tk] = JSON.parse(raw);
            } catch {
              todos[tk] = raw;
            }
          }
        }
        if (Object.keys(todos).length > 0) {
          modules['todos'] = todos;
          meta['todos'] = entry.label;
        }
        continue;
      }

      const raw = scopedStorage.getItem(entry.key);
      if (raw == null) continue;

      if (entry.isJson) {
        try {
          modules[entry.key] = JSON.parse(raw);
        } catch {
          modules[entry.key] = raw;
        }
      } else {
        modules[entry.key] = raw;
      }
      meta[entry.key] = entry.label;
    } catch (e) {
      logger.warn(`备份 ${entry.key} 失败:`, String(e));
    }
  }

  return {
    version: BACKUP_VERSION,
    exportedAt: new Date().toISOString(),
    app: '鑫之海运营手册',
    modules,
  };
}

export function downloadBackup() {
  try {
    const data = exportAllData();
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const dateStr = new Date().toISOString().slice(0, 10);
    a.href = url;
    a.download = `鑫之海数据备份-${dateStr}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    toast.success(`已导出 ${Object.keys(data.modules).length} 个模块数据`);
  } catch (e) {
    logger.error('导出备份失败:', String(e));
    toast.error('导出失败，请重试');
  }
}

export interface ImportResult {
  success: boolean;
  imported: string[];
  failed: string[];
  skipped: string[];
}

export function importBackup(file: File): Promise<ImportResult> {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const text = String(reader.result || '');
        const data = JSON.parse(text) as BackupData;

        if (!data.modules || typeof data.modules !== 'object') {
          toast.error('文件格式不正确');
          resolve({ success: false, imported: [], failed: [], skipped: [] });
          return;
        }

        const imported: string[] = [];
        const failed: string[] = [];
        const skipped: string[] = [];

        for (const [key, value] of Object.entries(data.modules)) {
          try {
            if (key === 'todos' && typeof value === 'object' && value) {
              // 还原所有日期待办
              const todoMap = value as Record<string, unknown>;
              let count = 0;
              for (const [tk, tv] of Object.entries(todoMap)) {
                try {
                  scopedStorage.setItem(tk, JSON.stringify(tv));
                  count++;
                } catch {
                  // 单条失败继续
                }
              }
              if (count > 0) imported.push(`待办(${count}天)`);
              else skipped.push('待办');
              continue;
            }

            if (typeof value === 'string') {
              scopedStorage.setItem(key, value);
            } else {
              scopedStorage.setItem(key, JSON.stringify(value));
            }
            imported.push(key);
          } catch (e) {
            logger.warn(`恢复 ${key} 失败:`, String(e));
            failed.push(key);
          }
        }

        resolve({ success: imported.length > 0, imported, failed, skipped });
      } catch (e) {
        logger.error('解析备份文件失败:', String(e));
        toast.error('文件解析失败，请确认是正确的备份文件');
        resolve({ success: false, imported: [], failed: [], skipped: [] });
      }
    };
    reader.onerror = () => {
      toast.error('文件读取失败');
      resolve({ success: false, imported: [], failed: [], skipped: [] });
    };
    reader.readAsText(file);
  });
}
